local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local KCookie = CS.Engine.Lib.KCookie
local UICommonHpAndEnergyNode = "Game.UI.FightTeam.UICommonHpAndEnergyNode"
local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
local MazeMgr = import('Game.Maze.MazeMgr')

---@class UIMazeTeamDialog
---@field bg                            	UnityEngine.UI.Button                   
---@field hero                          	UnityEngine.RectTransform               
---@field heroView                      	SuperScrollView.LoopGridView            
---@field closeBtn                      	UnityEngine.UI.Button                   
---@field title                         	UnityEngine.UI.Text                     
---@field Root                          	UnityEngine.RectTransform                          
local UIMazeTeamDialog = Class("UIMazeTeamDialog")

function UIMazeTeamDialog:__init() 
    self.isUseItem = false                 --是否时使用物品时的打开
    self.useItemId = nil         --使用的物品
    self._smallCardLoader = nil
end

function UIMazeTeamDialog:__delete()
    self.useItemId = nil        --使用物品
    self.isUseItem = false
    self._smallCardLoader = nil
end

function UIMazeTeamDialog:OnFocus(focus)
    if focus then
        MazeMgr:GetInstance():SetMazeMainUIActiveTrue()
    end
end

function UIMazeTeamDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UIMazeTeamDialog:Awake()
    local data = self.controller.Argument.parameters   --界面传参
    if data and data.useItemId then
        self.isUseItem = true
        self.useItemId = data.useItemId
    end

    self:FillSelfCf()
    self:FillSelf()
end

function UIMazeTeamDialog:FillSelfCf()
    SetButtonAction(self.closeBtn, Bind(self, self.OncloseBtn))
    SetButtonAction(self.bg, Bind(self, self.OncloseBtn))
end

function UIMazeTeamDialog:FillSelf()
    if self.isUseItem then
        CfUtils.FillText(self.title, localize("点击头像使用道具"))
    else
        CfUtils.FillText(self.title, localize("值班表"))
    end

    self:FillHeros()
end

--绘制所有的英雄
function UIMazeTeamDialog:FillHeros()
    local mazeTeamComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeTeamComponent, Constants.MazeTeamEntityId)

    local roleDatas = mazeTeamComp:GetRolesArr()
    self:SortRoles(roleDatas)
    self.heroView:InitGridView(#roleDatas, function(loopView, index)
        if index < 0 or index > #roleDatas - 1 then 
            return nil
        end
        local item = loopView:NewListViewItem("hero")
        local cardPar = item.transform:Find("head").transform
        local role = roleDatas[index + 1]

        local cardData = mazeTeamComp:GetFakeRoleData(role.id)

        if not self._smallCardLoader then
            self._smallCardLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
        end
        if self._smallCardLoader.IsSuccess then
            local go = cardPar.transform:Find("cell")
            if not go then 
                go = CfUtils.InstantiateGo(self._smallCardLoader.ResultObject, cardPar)
                go.name = "cell"
            end
            if go then
                CfUtils.RefeshCommonSmallHeroGo(go, cardData, Vector3(0.7, 0.7, 1), function()
                    if self.isUseItem then
                        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.useItemId, Constants.IDArea.Maze)
                        if goodsVo.effectType == Constants.GoodsEffectType.MazeCure then  --回复血量    
                            if checkNumber(role.hpPercent) >= 1 then
                                GameUtils.Toast(localize("满血不要使用"), 1)   
                            elseif checkNumber(role.hpPercent) <= 0 then
                                GameUtils.Toast(localize("角色已死亡，不能回复血量"), 1)   
                            else
                                ---使用物品
                                MazeMgr:GetInstance():MazeUseGoods(self.useItemId, role.isAssistant, role.id)
                                UIModule.CloseDialog(self.controller)
                            end
                        else
                            ---使用物品
                            MazeMgr:GetInstance():MazeUseGoods(self.useItemId, role.isAssistant, role.id)
                            UIModule.CloseDialog(self.controller)
                        end
                    else
                        --KCookie.Set(Constants.UICacheDataKeys.UICultivateMainCards, {cardData}) --全部的数据
                        --KCookie.Set(Constants.UICacheDataKeys.UICultivateMainPosition, 1)

                        if cardData.isAssistant == 1 then
                            CardUtils.ShowCardPreview({previewType = Constants.UICultivateCardPreviewType.Virtual, cards = {cardData}}, {
                                    {id = Constants.UITypeIds.UIMazeTeamDialog}
                                }
                            )
                        else
                            CardUtils.ShowCultivateMain({selectCardDojo = cardData}, {
                                { id = Constants.UITypeIds.UIMazeTeamDialog}
                            })
                        end


                        CfUtils.RefreshTopCommonEntrance()
                        MazeMgr:GetInstance():CloseMazeMainGameObject()
                    end
                end)
                go.transform.localPosition = Vector3(0, 0, 0)
            end
        end
        self._uiCommonHpAndEnergyNodeScr = CfUtils.GetLuaScr(item.transform:Find("CommonHpEnergyNode"), UICommonHpAndEnergyNode)
        if self._uiCommonHpAndEnergyNodeScr then
            self._uiCommonHpAndEnergyNodeScr:Refresh(role)
        end
        KTool.SetActive(item.transform:Find("isAssistant"), checkNumber(role.isAssistant) == 1)
        return item
    end);
    self.heroView:MovePanelToItemByRowColumn(0, 0);
end

function UIMazeTeamDialog:SortRoles(roleDatas)
    if not roleDatas then
        return roleDatas
    end

    table.sort(roleDatas, function(a, b)
        local cardVo1 = CardConfMgr:GetInstance():GetCardByRefId(a.cardId)
        local cardVo2 = CardConfMgr:GetInstance():GetCardByRefId(b.cardId)

        if not cardVo1 then 
            return true
        elseif not cardVo2 then
            return false
        end

        if checkNumber(cardVo1.rare) > checkNumber(cardVo2.rare) then 
            return true
        elseif checkNumber(cardVo1.rare) == checkNumber(cardVo2.rare) then
            if checkNumber(a.cardLevel) > checkNumber(b.cardLevel) then
                return true
            end
        end
        return false
    end)
end

function UIMazeTeamDialog:OncloseBtn()
    UIModule.CloseDialog(self.controller)
    --Events.Broadcast(Constants.EventNames.MazeMainUIActive,{isTrue = true})
end

function UIMazeTeamDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        MazeMgr:GetInstance():OpenMazeMainGameObject()
    end))
    return coWait
end

function UIMazeTeamDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._smallCardLoader) then
            self._smallCardLoader:Release()
            self._smallCardLoader = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMazeTeamDialog
